function esperar(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function* contarComAtraso(limite) {
  for (let i = 1; i <= limite; i++) {
    await esperar(300); // simula trabalho assíncrono entre valores
    yield i;
  }
}

async function exemplo() {
  const gerador = contarComAtraso(3);
  console.log(await gerador.next()); // { value: 1, done: false }, após ~300ms
  console.log(await gerador.next()); // { value: 2, done: false }
  console.log(await gerador.next()); // { value: 3, done: false }
  console.log(await gerador.next()); // { value: undefined, done: true }
}

exemplo();

function esperar(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

const fonteAssincrona = {
  [Symbol.asyncIterator]() {
    const dados = [10, 20, 30];
    let indice = 0;

    return {
      async next() {
        await esperar(100);
        if (indice < dados.length) {
          return { value: dados[indice++], done: false };
        }
        return { value: undefined, done: true };
      },
    };
  },
};

async function consumirManualmente() {
  for await (const valor of fonteAssincrona) {
    console.log(valor); // 10, depois 20, depois 30
  }
}

consumirManualmente();

function esperar(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function* gerarNumeros() {
  try {
    for (let i = 1; i <= 5; i++) {
      await esperar(200);
      yield i;
    }
  } finally {
    console.log("Limpeza executada: recursos libertados");
  }
}

async function processar() {
  try {
    for await (const numero of gerarNumeros()) {
      console.log("Recebido:", numero);
      if (numero === 3) {
        break; // provoca a chamada a return() no generator
      }
    }
  } catch (erro) {
    console.error("Falhou:", erro.message);
  }
}

processar();

async function* obterTodosOsUtilizadores(urlInicial) {
  let proximaUrl = urlInicial;

  while (proximaUrl) {
    const resposta = await fetch(proximaUrl);

    if (!resposta.ok) {
      throw new Error(`Falha ao obter página: ${resposta.status}`);
    }

    const pagina = await resposta.json();
    yield* pagina.resultados; // entrega cada utilizador individualmente

    proximaUrl = pagina.proximaPagina ?? null; // null quando não há mais páginas
  }
}

async function encontrarPrimeiroAdmin() {
  for await (const utilizador of obterTodosOsUtilizadores("/api/utilizadores?pagina=1")) {
    if (utilizador.role === "admin") {
      console.log("Encontrado:", utilizador.nome);
      break; // as páginas seguintes nunca chegam a ser pedidas
    }
  }
}

encontrarPrimeiroAdmin();

async function* lerStream(leitor) {
  try {
    while (true) {
      const { value, done } = await leitor.read();
      if (done) return;
      yield value; // cada value é tipicamente um Uint8Array
    }
  } finally {
    leitor.releaseLock();
  }
}

async function processarResposta(url) {
  const resposta = await fetch(url);
  const leitor = resposta.body.getReader();

  for await (const chunk of lerStream(leitor)) {
    console.log("Chunk recebido:", chunk.byteLength, "bytes");
  }
}

