function esperar(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function intervaloAssincrono(inicio, fim) {
  return {
    [Symbol.asyncIterator]() {
      let atual = inicio;
      return {
        async next() {
          await esperar(100);
          if (atual > fim) {
            return { value: undefined, done: true };
          }
          return { value: atual++, done: false };
        },
      };
    },
  };
}

async function somarAteLimite() {
  let soma = 0;

  for await (const numero of intervaloAssincrono(1, 10)) {
    soma += numero;
    console.log("Valor:", numero, "Soma:", soma);

    if (soma > 15) {
      break;
    }
  }

  console.log("Soma final:", soma);
}

somarAteLimite();

exercises.statement:
Dada a função já implementada obterPagina(pagina), que devolve uma Promise resolvida com { resultados: string[], temMaisPaginas: boolean }:

function obterPagina(pagina) {
  const todasAsPaginas = [
    ["maçã", "banana"],
    ["pera", "uva"],
    ["manga"],
  ];
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve({
        resultados: todasAsPaginas[pagina - 1] ?? [],
        temMaisPaginas: pagina < todasAsPaginas.length,
      });
    }, 150);
  });
}

Escreva uma async generator function obterTodosOsResultados() que chama obterPagina de forma sequencial (página 1, depois 2, etc.), produzindo (yield) cada item individualmente, e que para assim que temMaisPaginas for false, após entregar os itens dessa última página. Consuma-a com for await...of, imprimindo cada item, mas pare assim que tiverem sido impressos 4 itens no total, mesmo que existam mais páginas por buscar. Use um bloco finally dentro do generator para confirmar, com um console.log, que ele foi corretamente fechado.

exercises.solution_code:
function obterPagina(pagina) {
  const todasAsPaginas = [
    ["maçã", "banana"],
    ["pera", "uva"],
    ["manga"],
  ];
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve({
        resultados: todasAsPaginas[pagina - 1] ?? [],
        temMaisPaginas: pagina < todasAsPaginas.length,
      });
    }, 150);
  });
}

async function* obterTodosOsResultados() {
  let pagina = 1;

  try {
    while (true) {
      const { resultados, temMaisPaginas } = await obterPagina(pagina);
      yield* resultados;

      if (!temMaisPaginas) {
        return;
      }
      pagina++;
    }
  } finally {
    console.log("A fechar o generator de paginação");
  }
}

async function listarPrimeirosQuatro() {
  let contados = 0;

  for await (const item of obterTodosOsResultados()) {
    console.log(item);
    contados++;

    if (contados === 4) {
      break;
    }
  }
}

listarPrimeirosQuatro();

async function* mapAsync(iteravelAssincrono, funcaoTransformacao) {
  for await (const valor of iteravelAssincrono) {
    yield await funcaoTransformacao(valor);
  }
}

// Reaproveitando obterTodosOsResultados do exercício anterior
async function listarEmMaiusculas() {
  const iteravelTransformado = mapAsync(
    obterTodosOsResultados(),
    (item) => item.toUpperCase()
  );

  for await (const item of iteravelTransformado) {
    console.log(item);
  }
}

listarEmMaiusculas();
